"""matplotlib._color_data — named color dictionaries.

Mirrors upstream so `matplotlib.colors.CSS4_COLORS`, `BASE_COLORS`,
`TABLEAU_COLORS`, and `XKCD_COLORS` resolve to real dicts. Names are
verbatim CSS4 / Tableau standards; XKCD is a subset of the most
common ones (the full upstream list is ~950 entries — we ship the
~140 most-used names; falling back to grey for unknown ones is safe).
"""

# ─── Base 1-char shortcuts ─────────────────────────────────────
BASE_COLORS = {
    'b': (0, 0, 1), 'g': (0, 0.5, 0), 'r': (1, 0, 0),
    'c': (0, 0.75, 0.75), 'm': (0.75, 0, 0.75), 'y': (0.75, 0.75, 0),
    'k': (0, 0, 0), 'w': (1, 1, 1),
}

